30	// Report 是按学生核对学分的结果。
31	type Report struct {
32		StudentID string
33		Found     bool // 学生是否存在
34		// TotalCredits 已满足要求获得的学分之和；同一课程的多项要求各计一次，
35		// 同一要求无论通过多少次或同时有免修都只计一份。
36		TotalCredits int
37		Requirements []RequirementStatus
38		// Unmet 是未满足的要求编号（保持 Requirements 中的顺序）。
39		Unmet []string
40		// RejectedWaivers 是该学生被拒绝的免修申请及具体原因，按申请顺序。
41		RejectedWaivers []RejectedWaiver
42		// RevokedWaivers 是已撤销免修编号，按申请顺序。
43		RevokedWaivers []string
44	}
45	
46	// CheckStudent 按学生核对学分。查询没有记录的学生时 Found=false。
47	func (s *Store) CheckStudent(studentID string) Report {
48		rep := Report{StudentID: studentID}
49		if _, ok := s.studentByID[studentID]; !ok {
50			return rep
51		}
52		rep.Found = true
53	
54		// 汇总每项要求的通过修读（按结果提交先后）。
55		type seqEntry struct {
56			id  string
57			seq int
58		}
59		passOrder := map[string][]seqEntry{}
60		for _, e := range s.enrollments {
61			if e.StudentID != studentID || e.Result != Passed {
62				continue
63			}
64			passOrder[e.ReqID] = append(passOrder[e.ReqID], seqEntry{e.ID, e.ResultSeq})
65		}
66	
67		for _, r := range s.requirements {
68			if r.StudentID != studentID {
69				continue
70			}
71			st := RequirementStatus{Req: r, Course: s.courseByID[r.CourseID]}
72			entries := passOrder[r.ID]
73			sort.SliceStable(entries, func(i, j int) bool { return entries[i].seq < entries[j].seq })
74			for _, en := range entries {
75				st.PassedEnrollmentIDs = append(st.PassedEnrollmentIDs, en.id)
76			}
77	
78			if w := s.validWaiver(studentID, r.ID); w != nil {
79				// 有有效免修：以免修说明当前学分来源；修读历史同时保留。
80				st.Satisfied = true
81				st.Source = "waiver"
82				st.WaiverID = w.ID
83			} else if len(entries) > 0 {
84				// 没有有效免修时以最先提交的通过记录说明来源。
85				st.Satisfied = true
86				st.Source = "enrollment"
87				st.PassedEnrollmentID = entries[0].id
88			}
89	
90			if st.Satisfied && st.Course != nil {
91				rep.TotalCredits += st.Course.Credit
92			} else {
93				rep.Unmet = append(rep.Unmet, r.ID)
94			}
95			rep.Requirements = append(rep.Requirements, st)
96		}
97	
98		for _, w := range s.waivers {
99			if w.StudentID != studentID {
100				continue
101			}
102			switch w.Status {
103			case WaiverRejected:
104				rep.RejectedWaivers = append(rep.RejectedWaivers,
105					RejectedWaiver{Waiver: w, Reason: w.Reason})
106			case WaiverRevoked:
107				rep.RevokedWaivers = append(rep.RevokedWaivers, w.ID)
108			}
109		}
110		return rep
111	}
112	
113	// zhResult 将修读结果转为中文说明。
114	func zhResult(r Result) string {
115		switch r {
116		case Passed:
117			return "通过"
118		case Failed:
119			return "未通过"
120		default:
121			return "选课"
122		}
123	}
