126	func (rep Report) String() string {
127		if !rep.Found {
128			return fmt.Sprintf("学生 %s 不存在，没有任何记录", rep.StudentID)
129		}
130		var b []byte
131		b = append(b, fmt.Sprintf("学生 %s 核对结果\n", rep.StudentID)...)
132		b = append(b, fmt.Sprintf("总学分：%d\n", rep.TotalCredits)...)
133		if len(rep.Requirements) == 0 {
134			b = append(b, "课程要求：（无）\n"...)
135		} else {
136			b = append(b, "课程要求：\n"...)
137			for _, st := range rep.Requirements {
138				courseName := ""
139				credit := 0
140				if st.Course != nil {
141					courseName = st.Course.Name
142					credit = st.Course.Credit
143				}
144				if st.Satisfied {
145					switch st.Source {
146					case "waiver":
147						b = append(b, fmt.Sprintf(
148							"  - 要求 %s（课程 %s《%s》，%d 学分）：已满足，来源为有效免修 %s",
149							st.Req.ID, st.Req.CourseID, courseName, credit, st.WaiverID)...)
150						if len(st.PassedEnrollmentIDs) > 0 {
151							b = append(b, fmt.Sprintf("；另有通过修读历史 %v，不重复计学分",
152								st.PassedEnrollmentIDs)...)
153						}
154					case "enrollment":
155						b = append(b, fmt.Sprintf(
156							"  - 要求 %s（课程 %s《%s》，%d 学分）：已满足，来源为通过修读 %s",
157							st.Req.ID, st.Req.CourseID, courseName, credit,
158							st.PassedEnrollmentID)...)
159						if len(st.PassedEnrollmentIDs) > 1 {
160							b = append(b, fmt.Sprintf("（共通过 %d 次，仅计一次学分）",
161								len(st.PassedEnrollmentIDs))...)
162						}
163					}
164				} else {
165					b = append(b, fmt.Sprintf(
166						"  - 要求 %s（课程 %s《%s》，%d 学分）：未满足",
167						st.Req.ID, st.Req.CourseID, courseName, credit)...)
168				}
169				b = append(b, '\n')
170			}
171		}
172		if len(rep.Unmet) > 0 {
173			b = append(b, fmt.Sprintf("未满足要求：%v\n", rep.Unmet)...)
174		} else {
175			b = append(b, "未满足要求：（无）\n"...)
176		}
177		if len(rep.RejectedWaivers) > 0 {
178			b = append(b, "被拒绝的免修：\n"...)
179			for _, rj := range rep.RejectedWaivers {
180				b = append(b, fmt.Sprintf("  - 免修 %s（要求 %s，依据 %q）：%s\n",
181					rj.Waiver.ID, rj.Waiver.ReqID, rj.Waiver.Basis, rj.Reason)...)
182			}
183		}
184		if len(rep.RevokedWaivers) > 0 {
185			b = append(b, fmt.Sprintf("已撤销免修：%v（原依据与撤销状态保留在免修历史中）\n",
186				rep.RevokedWaivers)...)
187		}
188		return string(b)
189	}
