526		mustReq(t, s, "s1", "r2", "c2")
527		mustEnroll(t, s, "s1", "r1", "2024春", "e1")
528		if _, _, err := s.SubmitResult("s1", "e1", Failed); err != nil {
529			t.Fatal(err)
530		}
531		if _, _, err := s.ApplyWaiver("s1", "r2", "w1", "竞赛获奖"); err != nil {
532			t.Fatal(err)
533		}
534	
535		rep = s.CheckStudent("s1")
536		if rep.TotalCredits != 3 {
537			t.Fatalf("未通过不计学分、免修计学分，总学分应为 3，得到 %d", rep.TotalCredits)
538		}
539		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
540			t.Fatalf("未满足要求应为 [r1]，得到 %v", rep.Unmet)
541		}
542		if len(rep.Requirements) != 2 {
543			t.Fatalf("应列出全部 2 项要求，得到 %d", len(rep.Requirements))
544		}
545		if rep.Requirements[0].Satisfied {
546			t.Fatalf("r1 只有未通过，应未满足，得到 %+v", rep.Requirements[0])
547		}
548		if !rep.Requirements[1].Satisfied || rep.Requirements[1].Source != "waiver" ||
549			rep.Requirements[1].WaiverID != "w1" {
550			t.Fatalf("r2 应由有效免修满足，得到 %+v", rep.Requirements[1])
551		}
552	}
553	
554	// setupSharedEnrollments 建立两名学生就同一门 4 学分课程的同号要求 r1 与
555	// 同号修读 e1（同一学期），返回前、后提交结果的两名学生编号。
556	// 两份修读都应成功登记，初始为选课。
557	func setupSharedEnrollments(t *testing.T, s *Store) {
558		t.Helper()
559		mustStudent(t, s, "s1")
560		mustStudent(t, s, "s2")
561		mustCourse(t, s, "c1", "高等数学", 4)
562		mustReq(t, s, "s1", "r1", "c1")
563		mustReq(t, s, "s2", "r1", "c1")
564		mustEnroll(t, s, "s1", "r1", "2024春", "e1")
565		mustEnroll(t, s, "s2", "r1", "2024春", "e1")
566	
567		e1 := s.Enrollment("s1", "e1")
568		e2 := s.Enrollment("s2", "e1")
569		if e1 == nil || e2 == nil || e1 == e2 {
570			t.Fatalf("同号修读应在两名学生名下各成一条独立记录，得到 %p %p", e1, e2)
571		}
572		if e1.Result != Enrolled || e2.Result != Enrolled {
573			t.Fatalf("两份修读初始都应为选课，得到 %s %s", e1.Result, e2.Result)
574		}
575		// 各自核对均为 0 学分且要求未满足。
576		assertUnmetZero(t, s, "s1")
577		assertUnmetZero(t, s, "s2")
578	}
579	
580	// assertUnmetZero 核对该学生：0 学分、要求未满足、无任何通过修读历史。
581	func assertUnmetZero(t *testing.T, s *Store, student string) {
582		t.Helper()
583		rep := s.CheckStudent(student)
584		if rep.TotalCredits != 0 {
585			t.Fatalf("学生 %s 总学分应为 0，得到 %d", student, rep.TotalCredits)
586		}
587		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
588			t.Fatalf("学生 %s 的要求 r1 应未满足，得到 %v", student, rep.Unmet)
589		}
590		if st := rep.Requirements[0]; st.Satisfied || st.Source != "" ||
591			st.PassedEnrollmentID != "" || len(st.PassedEnrollmentIDs) != 0 {
592			t.Fatalf("学生 %s 的要求不应有来源或通过历史，得到 %+v", student, st)
593		}
594	}
595	
596	// assertPassedOwner 核对该学生的要求已满足、获得 4 学分，且来源指向本人的 e1。
597	func assertPassedOwner(t *testing.T, s *Store, student string) {
598		t.Helper()
599		rep := s.CheckStudent(student)
600		if rep.TotalCredits != 4 {
601			t.Fatalf("学生 %s 应只有本人获得 4 学分，得到 %d", student, rep.TotalCredits)
602		}
603		if len(rep.Unmet) != 0 {
604			t.Fatalf("学生 %s 的要求应已满足，未满足=%v", student, rep.Unmet)
605		}
606		st := rep.Requirements[0]
607		if !st.Satisfied || st.Source != "enrollment" || st.PassedEnrollmentID != "e1" {
608			t.Fatalf("学生 %s 的要求应由本人的通过修读 e1 满足，得到 %+v", student, st)
609		}
610		if len(st.PassedEnrollmentIDs) != 1 || st.PassedEnrollmentIDs[0] != "e1" {
611			t.Fatalf("学生 %s 的通过历史应只有本人的 e1，得到 %v",
612				student, st.PassedEnrollmentIDs)
613		}
614		if e := s.Enrollment(student, "e1"); e == nil || e.Result != Passed {
615			t.Fatalf("学生 %s 本人的修读 e1 应为通过，得到 %+v", student, e)
616		}
617	}
618	
619	// assertEnrResult 直接核对某学生名下 e1 的结果。
620	func assertEnrResult(t *testing.T, s *Store, student string, want Result) {
621		t.Helper()
622		e := s.Enrollment(student, "e1")
623		if e == nil {
624			t.Fatalf("学生 %s 名下应存在修读 e1", student)
625		}
626		if e.Result != want {
627			t.Fatalf("学生 %s 的修读 e1 应为 %s，得到 %s", student, want, e.Result)
628		}
629	}
630	
631	// TestSharedEnrollmentIDsResultOwnership 两名学生共享要求编号与修读编号时，
632	// 提交结果只能写到本人名下；先由 s1 通过、再由 s2 未通过。
633	func TestSharedEnrollmentIDsResultOwnership(t *testing.T) {
634		s := NewStore()
635		setupSharedEnrollments(t, s)
636	
637		// 给 s1 的修读提交通过：只有 s1 获得 4 学分、要求满足、来源是本人的 e1。
638		if _, changed, err := s.SubmitResult("s1", "e1", Passed); err != nil || !changed {
639			t.Fatalf("s1 提交通过应成功，changed=%v err=%v", changed, err)
640		}
641		assertPassedOwner(t, s, "s1")
642		// 另一名学生仍是选课：不能因为编号相同拿到学分或被改成通过。
643		assertEnrResult(t, s, "s2", Enrolled)
644		assertUnmetZero(t, s, "s2")
645	
646		// 随后给 s2 的同号修读提交未通过：s2 仍为 0 学分、要求未满足。
647		if _, changed, err := s.SubmitResult("s2", "e1", Failed); err != nil || !changed {
648			t.Fatalf("s2 提交未通过应成功，changed=%v err=%v", changed, err)
649		}
650		assertEnrResult(t, s, "s2", Failed)
651		assertUnmetZero(t, s, "s2")
652		// s1 原来的通过结果、学分与来源均保持不变。
653		assertEnrResult(t, s, "s1", Passed)
654		assertPassedOwner(t, s, "s1")
655	
656		// 两人结果不同，应分别被接受，不能被误判为同一次修读的结果冲突：
657		// 各自重复提交相同结果均幂等成功。
658		if _, changed, err := s.SubmitResult("s1", "e1", Passed); err != nil || changed {
659			t.Fatalf("s1 重复通过应幂等，changed=%v err=%v", changed, err)
660		}
661		if _, changed, err := s.SubmitResult("s2", "e1", Failed); err != nil || changed {
662			t.Fatalf("s2 重复未通过应幂等，changed=%v err=%v", changed, err)
663		}
664		assertPassedOwner(t, s, "s1")
665		assertEnrResult(t, s, "s2", Failed)
666		assertUnmetZero(t, s, "s2")
667	}
668	
669	// TestSharedEnrollmentIDsResultOwnershipReversed 与上一个用例相同的归属保护，
670	// 但交换两名学生的登记/处理顺序：先 s2 未通过、再 s1 通过，结论必须一致，
671	// 证明归属不依赖先登记或先处理哪名学生。
672	func TestSharedEnrollmentIDsResultOwnershipReversed(t *testing.T) {
673		s := NewStore()
674		// 先登记 s2 再登记 s1（与 setupSharedEnrollments 顺序相反）。
675		mustStudent(t, s, "s2")
676		mustStudent(t, s, "s1")
677		mustCourse(t, s, "c1", "高等数学", 4)
678		mustReq(t, s, "s2", "r1", "c1")
679		mustReq(t, s, "s1", "r1", "c1")
680		mustEnroll(t, s, "s2", "r1", "2024春", "e1")
681		mustEnroll(t, s, "s1", "r1", "2024春", "e1")
682		assertUnmetZero(t, s, "s1")
683		assertUnmetZero(t, s, "s2")
684	
685		// 后登记的 s2 先提交未通过。
686		if _, changed, err := s.SubmitResult("s2", "e1", Failed); err != nil || !changed {
687			t.Fatalf("s2 提交未通过应成功，changed=%v err=%v", changed, err)
688		}
689		assertEnrResult(t, s, "s2", Failed)
690		assertUnmetZero(t, s, "s2")
691		assertEnrResult(t, s, "s1", Enrolled)
692		assertUnmetZero(t, s, "s1")
693	
694		// s1 随后提交通过。
695		if _, changed, err := s.SubmitResult("s1", "e1", Passed); err != nil || !changed {
696			t.Fatalf("s1 提交通过应成功，changed=%v err=%v", changed, err)
697		}
698		assertPassedOwner(t, s, "s1")
699		assertEnrResult(t, s, "s2", Failed)
700		assertUnmetZero(t, s, "s2")
701	}
702	
703	// TestSubmitResultUnknownEnrollmentUnderOtherStudent 修读编号只存在于 s1 名下时，
704	// 用 s2 的名义提交结果必须明确报“s2 名下没有该修读”，不能借用 s1 的修读，
705	// 也不能在 s2 名下补出一条新记录。
706	func TestSubmitResultUnknownEnrollmentUnderOtherStudent(t *testing.T) {
707		s := NewStore()
708		mustStudent(t, s, "s1")
709		mustStudent(t, s, "s2")
710		mustCourse(t, s, "c1", "高等数学", 4)
711		mustReq(t, s, "s1", "r1", "c1")
712		mustEnroll(t, s, "s1", "r1", "2024春", "e1")
713	
714		_, _, err := s.SubmitResult("s2", "e1", Passed)
715		if err == nil || !strings.Contains(err.Error(), "s2") ||
716			!strings.Contains(err.Error(), "e1") {
717			t.Fatalf("用 s2 的名义提交只属于 s1 的修读应明确报 s2 名下无此修读，得到 %v", err)
718		}
719		if !strings.Contains(err.Error(), "不存在") {
720			t.Fatalf("错误信息应明确说明名下不存在，得到 %v", err)
721		}
722	
723		// 不能借用 s1 的修读：s1 的 e1 仍是选课。
724		assertEnrResult(t, s, "s1", Enrolled)
725		// 不能为 s2 补出新记录。
726		if e := s.Enrollment("s2", "e1"); e != nil {
727			t.Fatalf("拒绝后不应在 s2 名下补出修读，得到 %+v", e)
728		}
729		if n := len(s.Enrollments("s2")); n != 0 {
730			t.Fatalf("s2 不应有任何修读记录，得到 %d 条", n)
731		}
732		// 两人的修读状态、要求满足情况和总学分都与提交前一致。
733		assertUnmetZero(t, s, "s1")
734		if rep := s.CheckStudent("s2"); rep.TotalCredits != 0 ||
735			len(rep.Requirements) != 0 || len(rep.Unmet) != 0 {
736			t.Fatalf("s2 本就没有要求，拒绝后核对结果不应变化，得到 %+v", rep)
737		}
738	}
739	
740	// TestSharedEnrollmentResultChangeRejectedKeepsBoth 一名学生已提交结果后，
741	// 再把本人这份修读改成另一结果仍按现有规则拒绝并保留原结果；
742	// 另一名学生的同号修读保持原样。
743	func TestSharedEnrollmentResultChangeRejectedKeepsBoth(t *testing.T) {
744		s := NewStore()
745		setupSharedEnrollments(t, s)
746	
747		if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
748			t.Fatal(err)
749		}
750		if _, _, err := s.SubmitResult("s2", "e1", Failed); err != nil {
751			t.Fatal(err)
752		}
753	
754		// s1 已通过，改成未通过：拒绝并保留通过。
755		if _, _, err := s.SubmitResult("s1", "e1", Failed); err == nil {
756			t.Fatal("s1 通过后改提未通过应被拒绝")
757		}
758		assertEnrResult(t, s, "s1", Passed)
759		assertPassedOwner(t, s, "s1")
760		// s2 的同号修读保持未通过、0 学分。
761		assertEnrResult(t, s, "s2", Failed)
762		assertUnmetZero(t, s, "s2")
763	
764		// s2 已未通过，改成通过：拒绝并保留未通过；s1 不受影响。
765		if _, _, err := s.SubmitResult("s2", "e1", Passed); err == nil {
766			t.Fatal("s2 未通过后改提通过应被拒绝")
767		}
768		assertEnrResult(t, s, "s2", Failed)
769		assertUnmetZero(t, s, "s2")
770		assertEnrResult(t, s, "s1", Passed)
771		assertPassedOwner(t, s, "s1")
772	}
